def column_totals(rows):
    if not rows:
        return []
    result = []
    num_cols = len(rows[0])
    for i in range(num_cols):
        total = 0
        has_numeric = False
        for r in rows:
            if isinstance(r[i], (int, float)):
                total += r[i]
                has_numeric = True
        if has_numeric:
            result.append(total)
        else:
            result.append("")
    return result

